int main() {
    PA11.InitAsAFOutOD(6, decltype(PA11)::PuPd::Floating);
    PA12.InitAsAFOutOD(6, decltype(PA12)::PuPd::Floating);
    PB6.InitAsAFOutOD(6, decltype(PB6)::PuPd::Floating);
    PB7.InitAsAFOutOD(6, decltype(PB7)::PuPd::Floating);
    PC13.InitAsOutPP();
    PC14.InitAsOutPP();
    PC15.InitAsOutPP();
    PA15.InitAsOutPP();
    PA8.InitAsAFOutPP(2);
    PB3.InitAsAFOutPP(1);
    PA15.SetOutputLow();
    PWMGenerator1 pwm(10000); // 10KHz PWM
    pwm.EnableChannel<1>();
    pwm.EnableChannel<2>();
    DS18B20<decltype(PB5)> board_temper_sensor(PB5);
    if (board_temper_sensor.Present()) {
        PA15.SetOutputHigh();
    }
    I2CDevice1 i2c1(true, 0x00, I2CDevice1::Speed::Standard100KHz);
    using INA219 = INA219<I2CDevice1>;
    INA219 ina219(i2c1, 0x40, INA219::PGAGain::Gain2, INA219::ADCResolution::BIT12, INA219::Mode::ShuntBusContinuous);
    ina219.Calibrate(10, 5000);
    I2CDevice2 i2c2(true, 0x00, I2CDevice2::Speed::Fast400KHz);
    SSD1315 ssd1315(i2c2);
    CharactersSet SourceHanSans(font_SourceHanSans_data, sizeof(font_SourceHanSans_data), font_SourceHanSans_header, count_of(font_SourceHanSans_header));
    ssd1315.DrawText(0, 0, SourceHanSans, decltype(ssd1315)::U32Drawable(U"硬件自检中"));
    ssd1315.Present();
    board_temper_sensor.StartConversion();
    timer_sleep(1000000);
    PC15.SetOutputHigh();
    PC14.SetOutputLow();
    PC13.SetOutputHigh();
    pwm.SetDuty<1>(30);
    pwm.SetDuty<2>(60);
    while (true) {
        float volt = ina219.GetBusVoltage();
        float current = ina219.GetCurrent();
        u32 power = static_cast<u32>(volt * current);
        float board_tem = 0.0f;
        PA15.SetOutputLow();
        board_temper_sensor.ReadTemper(board_tem);
        board_temper_sensor.StartConversion();
        u32 led_tem = 0;
        ssd1315.DrawText(0, 0, SourceHanSans, decltype(ssd1315)::AsciiDrawable("OreLight Beta V0.1"));
        ssd1315.DrawText(0, 16, SourceHanSans,
            decltype(ssd1315)::FloatDrawable(volt, 2, 1),
            decltype(ssd1315)::AsciiDrawable("V ")
        );
        ssd1315.DrawText(50, 16, SourceHanSans,
            decltype(ssd1315)::FloatDrawable(current, 1, 2),
            decltype(ssd1315)::AsciiDrawable("A ")
        );
        ssd1315.DrawText(100, 16, SourceHanSans,
            decltype(ssd1315)::IntegerDrawable(power, 2),
            decltype(ssd1315)::AsciiDrawable("W")
        );
        ssd1315.DrawText(0, 32, SourceHanSans,
            decltype(ssd1315)::U32Drawable(U"板上温度 "),
            decltype(ssd1315)::FloatDrawable(board_tem, 2, 2),
            decltype(ssd1315)::U32Drawable(U"℃ ")
        );
        ssd1315.DrawText(0, 48, SourceHanSans,
            decltype(ssd1315)::U32Drawable(U"灯珠温度 "),
            decltype(ssd1315)::IntegerDrawable(led_tem, 2),
            decltype(ssd1315)::U32Drawable(U"℃ ")
        );
        ssd1315.Present();
    }
}